   254	static int probe_parse_startup_uptime(int argc, char *argv[],
   255	                                      uint64_t *target_ms)
   256	{
   257	  const char *cursor;
   258	  uint32_t value = 0;
   259	
   260	  if (argc == 1)
   261	    {
   262	      *target_ms = MIN_BLE_STARTUP_UPTIME_MS;
   263	      return 0;
   264	    }
   265	
   266	  if (argc == 2 && argv[1][0] != '\0')
   267	    {
   268	      for (cursor = argv[1]; *cursor != '\0'; cursor++)
   269	        {
   270	          if (*cursor < '0' || *cursor > '9')
   271	            {
   272	              goto invalid;
   273	          }
   274	
   275	          value = value * 10u + (uint32_t)(*cursor - '0');
   276	          if (value > 15000u)
   277	            {
   278	              goto invalid;
   279	            }
   280	          }
   281	
   282	      if (value >= 5000u && value <= 15000u && value % 250u == 0)
   283	        {
   284	          *target_ms = value;
   285	          return 0;
   286	        }
   287	    }
   288	
   289	invalid:
   290	  printf("Usage: openvela_ble_probe "
   291	         "[min_uptime_ms: 5000..15000, step 250]\n");
   292	  return -1;
   293	}
