   350	static int probe_imu_read(int fd, uint8_t addr, uint8_t reg,
   351	                          uint8_t *value, size_t length)
   352	{
   353	  struct i2c_msg_s messages[2];
   354	
   355	  messages[0].frequency = PROBE_IMU_I2C_FREQUENCY;
   356	  messages[0].addr = addr;
   357	  messages[0].flags = I2C_M_NOSTOP;
   358	  messages[0].buffer = &reg;
   359	  messages[0].length = 1;
   360	  messages[1].frequency = PROBE_IMU_I2C_FREQUENCY;
   361	  messages[1].addr = addr;
   362	  messages[1].flags = I2C_M_READ | I2C_M_NOSTART;
   363	  messages[1].buffer = value;
   364	  messages[1].length = length;
   365	
   366	  return probe_imu_transfer(fd, messages, 2);
