   405	static bool probe_detect_imu(void)
   406	{
   407	  static const uint8_t addresses[] = {0x6a, 0x6b};
   408	  uint8_t whoami;
   409	  bool detected = false;
   410	  int fd;
   411	  int ret;
   412	  size_t i;
   413	
   414	  fd = open(PROBE_IMU_I2C_DEV, O_RDONLY);
   415	  if (fd < 0)
   416	    {
   417	      printf("openvela_ble_probe: IMU probe open %s failed errno=%d\n",
   418	             PROBE_IMU_I2C_DEV, errno);
   419	      printf("openvela_ble_probe: IMU not detected at 0x6a or 0x6b\n");
   420	      return false;
   421	    }
   422	
   423	  for (i = 0; i < sizeof(addresses); i++)
   424	    {
   425	      whoami = 0;
   426	      ret = probe_imu_read(fd, addresses[i], PROBE_IMU_WHO_AM_I_REG,
   427	                           &whoami, 1);
   428	      printf("openvela_ble_probe: IMU probe addr=0x%02x transport=%d"
   429	             " whoami=0x%02x\n",
   430	             addresses[i], ret, whoami);
   431	      if (ret == 0 && whoami == PROBE_IMU_WHO_AM_I_VALUE)
   432	        {
   433	          printf("openvela_ble_probe: IMU detected addr=0x%02x"
   434	                 " whoami=0x6a\n", addresses[i]);
   435	          detected = true;
   436	        }
   437	    }
   438	
   439	  close(fd);
   440	  if (!detected)
   441	    {
   442	      printf("openvela_ble_probe: IMU not detected at 0x6a or 0x6b\n");
   443	    }
   444	
   445	  return detected;
   446	}
