   448	static int probe_get_monotonic_sample(uint64_t *out_us,
   449	                                      struct timespec *raw_time)
   450	{
   451	  struct timespec now;
   452	  uint64_t raw_us;
   453	  uint32_t low_us;
   454	  uint64_t extended_us;
   455	  bool log_enabled = false;
   456	  int error;
   457	
   458	  /* The SF32LB52 monotonic source can expose a 32-bit microsecond rollover.
   459	   * Sample and extend that counter under the same short lock so cross-thread
   460	   * ordering cannot join a pre-wrap sample to a post-wrap epoch.  Callers
   461	   * still transfer timestamps through their existing release/acquire SPSC
   462	   * slots rather than sharing mutable 64-bit fields.
   463	   */
   464	
   465	  pthread_mutex_lock(&g_monotonic_lock);
   466	  if (clock_gettime(CLOCK_MONOTONIC, &now) < 0)
   467	    {
   468	      error = errno;
   469	      pthread_mutex_unlock(&g_monotonic_lock);
   470	      errno = error;
   471	      return -1;
   472	    }
   473	
   474	  raw_us = (uint64_t)now.tv_sec * 1000000ULL +
   475	           (uint64_t)now.tv_nsec / 1000ULL;
   476	  low_us = (uint32_t)raw_us;
   477	  if (!g_monotonic_extended_valid)
   478	    {
   479	      g_monotonic_epoch_us = raw_us & ~UINT64_C(0xffffffff);
   480	      g_monotonic_extended_valid = true;
   481	      log_enabled = true;
   482	    }
   483	  else if (low_us < g_monotonic_last_low_us &&
   484	           g_monotonic_last_low_us - low_us > UINT32_C(0x80000000))
   485	    {
   486	      g_monotonic_epoch_us += UINT64_C(0x100000000);
   487	    }
   488	
   489	  extended_us = g_monotonic_epoch_us + low_us;
   490	  if (extended_us < g_monotonic_last_us)
   491	    {
   492	      extended_us = g_monotonic_last_us;
   493	    }
   494	
   495	  g_monotonic_last_low_us = low_us;
   496	  g_monotonic_last_us = extended_us;
   497	  *out_us = extended_us;
   498	  if (raw_time != NULL)
   499	    {
   500	      *raw_time = now;
   501	    }
   502	
   503	  pthread_mutex_unlock(&g_monotonic_lock);
   504	  if (log_enabled)
   505	    {
   506	      printf("openvela_ble_probe: monotonic 64-bit epoch extension enabled\n");
   507	    }
   508	
   509	  return 0;
   510	}
   511	
   512	static int probe_get_monotonic_us(uint64_t *out_us)
   513	{
   514	  return probe_get_monotonic_sample(out_us, NULL);
   515	}
