   517	static void probe_timespec_add_ms(struct timespec *time, uint32_t ms)
   518	{
   519	  uint64_t nsec = (uint64_t)time->tv_nsec +
   520	                  (uint64_t)ms * 1000000ULL;
   521	
   522	  time->tv_sec += (time_t)(nsec / 1000000000ULL);
   523	  time->tv_nsec = (long)(nsec % 1000000000ULL);
   524	}
