   784	                 " fifo_words_read=%lu gyro_samples=%lu accel_samples=%lu"
   785	                 " paired_six_axis_samples=%lu fifo_overrun=%lu"
   786	                 " fifo_smart_full=%lu max_fifo_depth_words=%lu"
   787	                 " unexpected=%lu i2c_errors=%lu timeouts=%lu"
   788	                 " timeout_status_polls=%lu fifo_recovery_attempts=%lu"
   789	                 " fifo_recovery_success=%lu fifo_recovery_failed=%lu"
   790	                 " imu_ring_full=%lu imu_gap_samples=%lu"
   791	                 " fifo_data_read_transfers=%lu fifo_data_read_words=%lu"
   792	                 " fifo_data_read_max_bytes=%lu"
   793	                 " fifo_data_read_chunk_bytes=%u\n",
   794	                 (unsigned long long)((now_us - start_us) / 1000),
   795	                 (unsigned long)fifo_irq_count,
   796	                 (unsigned long)fifo_wake_count,
   797	                 (unsigned long)fifo_words_read,
   798	                 (unsigned long)gyro_samples,
   799	                 (unsigned long)accel_samples,
   800	                 (unsigned long)paired_samples,
   801	                 (unsigned long)fifo_overrun,
   802	                 (unsigned long)fifo_smart_full,
   803	                 (unsigned long)max_fifo_depth_words,
   804	                 (unsigned long)unexpected_frames,
   805	                 (unsigned long)i2c_errors, (unsigned long)timeouts,
   806	                 (unsigned long)timeout_status_polls,
   807	                 (unsigned long)fifo_recovery_attempts,
   808	                 (unsigned long)fifo_recovery_success,
   809	                 (unsigned long)fifo_recovery_failed,
   810	                 (unsigned long)game_imu_stats.ring_full,
   811	                 (unsigned long)game_imu_stats.gap_samples,
   812	                 (unsigned long)fifo_data_read_transfers,
   813	                 (unsigned long)fifo_data_read_words,
   814	                 (unsigned long)fifo_data_read_max_bytes,
