   832	            {
   833	              timeouts++;
   834	              timeout_status_polls++;
   835	              ret = probe_imu_read(fd, PROBE_IMU_ADDR,
   836	                                   PROBE_IMU_FIFO_STATUS1,
   837	                                   status, sizeof(status));
   838	              if (ret != 0)
   839	                {
   840	                  i2c_errors++;
   841	                  expected_valid = false;
   842	                  continue;
   843	                }
   844	
   845	              status_ready = true;
   846	              if ((status[1] & 0x60) == 0 &&
   847	                  ((status[1] & 0x10) != 0 ||
   848	                   probe_imu_fifo_depth(status) == 0))
