   856	                     " errno=%d\n", errno);
   857	              break;
   858	            }
   859	        }
   860	      else
   861	        {
   862	          fifo_wake_count++;
   863	        }
   864	
   865	      for (;;)
   866	        {
   867	          uint16_t depth;
   868	          uint16_t pattern;
   869	          uint16_t words_to_read;
   870	          uint64_t drain_now_us;
   871	          bool watermark;
   872	          bool empty;
   873	          bool smart_full;
   874	          bool overrun;
   875	
   876	          if (!status_ready)
   877	            {
   878	              ret = probe_imu_read(fd, PROBE_IMU_ADDR,
   879	                                   PROBE_IMU_FIFO_STATUS1,
   880	                                   status, sizeof(status));
   881	              if (ret != 0)
   882	                {
   883	                  i2c_errors++;
   884	                  expected_valid = false;
   885	                  break;
   886	                }
   887	            }
   888	
   889	          status_ready = false;
   890	
   891	          if (probe_get_monotonic_us(&drain_now_us) < 0)
   892	            {
   893	              printf("openvela_ble_probe: IMU FIFO timestamp failed"
   894	                     " errno=%d\n", errno);
   895	              goto stop_irq;
   896	            }
   897	
   898	          depth = probe_imu_fifo_depth(status);
   899	          empty = (status[1] & 0x10) != 0;
   900	          smart_full = (status[1] & 0x20) != 0;
   901	          overrun = (status[1] & 0x40) != 0;
   902	          watermark = (status[1] & 0x80) != 0;
   903	          pattern = (uint16_t)status[2] |
   904	                    ((uint16_t)(status[3] & 0x03) << 8);
   905	
   906	          if (depth > max_fifo_depth_words)
   907	            {
   908	              max_fifo_depth_words = depth;
   909	            }
   910	
   911	          if (watermark && !wake_watermark_seen)
   912	            {
   913	              fifo_watermark_events++;
   914	              wake_watermark_seen = true;
   915	            }
   916	
   917	          if (smart_full && !wake_smart_full_seen)
   918	            {
   919	              fifo_smart_full++;
   920	              wake_smart_full_seen = true;
   921	            }
   922	
   923	          if (overrun && !wake_overrun_seen)
   924	            {
   925	              fifo_overrun++;
   926	              wake_overrun_seen = true;
   927	            }
   928	
   929	          if (smart_full)
   930	            {
   931	              if (smart_full_streak < UINT8_MAX)
   932	                {
   933	                  smart_full_streak++;
   934	                }
   935	            }
   936	          else
   937	            {
   938	              smart_full_streak = 0;
   939	            }
   940	
   941	          if (depth >= PROBE_IMU_FIFO_NEAR_FULL_WORDS)
   942	            {
   943	              if (near_full_streak < UINT8_MAX)
   944	                {
   945	                  near_full_streak++;
   946	                }
   947	            }
   948	          else
   949	            {
   950	              near_full_streak = 0;
   951	            }
   952	
   953	          if (overrun)
   954	            {
   955	              recovery_reason = "overrun";
   956	            }
   957	          else if (smart_full_streak >=
   958	                   PROBE_IMU_FIFO_SMART_FULL_LIMIT)
   959	            {
   960	              recovery_reason = "smart-full";
   961	            }
   962	          else if (near_full_streak >= PROBE_IMU_FIFO_NEAR_FULL_LIMIT)
   963	            {
   964	              recovery_reason = "near-full";
   965	            }
   966	
   967	          if (recovery_reason != NULL)
   968	            {
   969	              recovery_depth = depth;
   970	              break;
   971	            }
   972	
   973	          if (empty || depth == 0)
   974	            {
   975	              break;
   976	            }
   977	
   978	          words_to_read = depth;
   979	          while (words_to_read > 0)
   980	            {
   981	              uint16_t chunk_words = MIN(words_to_read,
   982	                PROBE_IMU_FIFO_READ_CHUNK_BYTES / 2);
   983	              uint16_t chunk_index;
   984	              size_t chunk_bytes = (size_t)chunk_words * 2;
   985	
   986	              ret = probe_imu_read(fd, PROBE_IMU_ADDR,
   987	                                   PROBE_IMU_FIFO_DATA_OUT_L,
   988	                                   fifo_data, chunk_bytes);
   989	              if (ret != 0)
   990	                {
   991	                  i2c_errors++;
   992	                  expected_valid = false;
   993	                  break;
   994	                }
   995	
   996	              fifo_data_read_transfers++;
   997	              fifo_data_read_words += chunk_words;
   998	              if (chunk_bytes > fifo_data_read_max_bytes)
   999	                {
  1000	                  fifo_data_read_max_bytes = chunk_bytes;
  1001	                }
  1002	
  1003	              fifo_words_read += chunk_words;
  1004	              for (chunk_index = 0; chunk_index < chunk_words; chunk_index++)
  1005	                {
  1006	                  struct probe_imu_sample sample;
  1007	                  uint8_t pattern_word = (uint8_t)(pattern %
  1008	                    PROBE_IMU_FIFO_PATTERN_WORDS);
  1009	                  size_t word_offset = (size_t)chunk_index * 2;
  1010	                  int16_t raw;
  1011	
  1012	                  words_to_read--;
  1013	
  1014	                  if (expected_valid && pattern_word != expected_pattern)
  1015	                    {
  1016	                      unexpected_frames++;
  1017	                      if (pattern_error_streak < UINT8_MAX)
  1018	                        {
  1019	                          pattern_error_streak++;
  1020	                        }
  1021	
  1022	                      pattern_valid_streak = 0;
  1023	                      gyro_axis_mask = 0;
  1024	                      accel_axis_mask = 0;
  1025	                      gyro_ready = false;
  1026	                    }
  1027	                  else
  1028	                    {
  1029	                      if (pattern_valid_streak <
  1030	                          PROBE_IMU_FIFO_PATTERN_WORDS)
  1031	                        {
  1032	                          pattern_valid_streak++;
  1033	                        }
  1034	
  1035	                      if (pattern_valid_streak >=
  1036	                          PROBE_IMU_FIFO_PATTERN_WORDS)
