  1476	static void probe_launch_imu_raw_if_pending(void)
  1477	{
  1478	  pthread_t thread;
  1479	  bool launch;
  1480	  int detach_ret;
  1481	  int ret;
  1482	
  1483	  pthread_mutex_lock(&g_state_lock);
  1484	  launch = g_imu_raw_launch_pending && !g_imu_raw_launch_attempted;
  1485	  if (launch)
  1486	    {
  1487	      g_imu_raw_launch_pending = false;
  1488	      g_imu_raw_launch_attempted = true;
  1489	    }
  1490	  pthread_mutex_unlock(&g_state_lock);
  1491	
  1492	  if (!launch)
  1493	    {
  1494	      return;
  1495	    }
  1496	
  1497	  ret = pthread_create(&thread, NULL, probe_imu_raw_thread, NULL);
  1498	  printf("openvela_ble_probe: IMU raw pthread create ret=%d\n", ret);
  1499	  if (ret != 0)
  1500	    {
  1501	      return;
  1502	    }
  1503	
  1504	  pthread_mutex_lock(&g_state_lock);
  1505	  g_imu_raw_started = true;
  1506	  pthread_mutex_unlock(&g_state_lock);
  1507	
  1508	  detach_ret = pthread_detach(thread);
  1509	  printf("openvela_ble_probe: IMU raw pthread detach ret=%d\n", detach_ret);
  1510	}
