  1582	static uint32_t probe_get_le32(const uint8_t *value)
  1583	{
  1584	  return (uint32_t)value[0] |
  1585	         ((uint32_t)value[1] << 8) |
  1586	         ((uint32_t)value[2] << 16) |
  1587	         ((uint32_t)value[3] << 24);
  1588	}
  1589	
  1590	static void probe_put_le32(uint8_t *value, uint32_t number)
  1591	{
  1592	  value[0] = (uint8_t)number;
  1593	  value[1] = (uint8_t)(number >> 8);
  1594	  value[2] = (uint8_t)(number >> 16);
  1595	  value[3] = (uint8_t)(number >> 24);
  1596	}
  1597	
  1598	static uint16_t probe_get_le16(const uint8_t *value)
  1599	{
  1600	  return (uint16_t)value[0] | ((uint16_t)value[1] << 8);
  1601	}
