  1605	  value[0] = (uint8_t)number;
  1606	  value[1] = (uint8_t)(number >> 8);
  1607	}
  1608	
  1609	static uint64_t probe_get_le64(const uint8_t *value)
  1610	{
  1611	  return (uint64_t)value[0] |
  1612	         ((uint64_t)value[1] << 8) |
  1613	         ((uint64_t)value[2] << 16) |
  1614	         ((uint64_t)value[3] << 24) |
  1615	         ((uint64_t)value[4] << 32) |
  1616	         ((uint64_t)value[5] << 40) |
  1617	         ((uint64_t)value[6] << 48) |
  1618	         ((uint64_t)value[7] << 56);
  1619	}
  1620	
  1621	static void probe_put_le64(uint8_t *value, uint64_t number)
  1622	{
  1623	  value[0] = (uint8_t)number;
  1624	  value[1] = (uint8_t)(number >> 8);
  1625	  value[2] = (uint8_t)(number >> 16);
  1626	  value[3] = (uint8_t)(number >> 24);
  1627	  value[4] = (uint8_t)(number >> 32);
  1628	  value[5] = (uint8_t)(number >> 40);
  1629	  value[6] = (uint8_t)(number >> 48);
  1630	  value[7] = (uint8_t)(number >> 56);
  1631	}
  1632	
  1633	static uint16_t probe_crc16_ccitt_false(const uint8_t *value, size_t length)
  1634	{
  1635	  uint16_t crc = 0xffff;
  1636	  size_t i;
  1637	  uint8_t bit;
  1638	
  1639	  for (i = 0; i < length; i++)
  1640	    {
  1641	      crc ^= (uint16_t)value[i] << 8;
  1642	      for (bit = 0; bit < 8; bit++)
  1643	        {
  1644	          crc = (crc & 0x8000) != 0 ?
  1645	                (uint16_t)((crc << 1) ^ 0x1021) :
  1646	                (uint16_t)(crc << 1);
  1647	        }
  1648	    }
  1649	
  1650	  return crc;
  1651	}
  1652	
  1653	static bt_status_t probe_notify(gatts_handle_t srv_handle,
  1654	                                uint8_t *value, uint16_t length)
  1655	{
  1656	  bt_address_t peer_addr;
  1657	  bool ready;
  1658	
  1659	  pthread_mutex_lock(&g_state_lock);
  1660	  ready = g_peer_connected && g_notify_enabled;
  1661	  memcpy(&peer_addr, &g_peer_addr, sizeof(peer_addr));
  1662	  pthread_mutex_unlock(&g_state_lock);
  1663	
  1664	  if (!ready)
  1665	    {
  1666	      printf("openvela_ble_probe: TX notification not subscribed\n");
  1667	      return BT_STATUS_NOT_READY;
  1668	    }
  1669	
  1670	  return bt_gatts_notify(srv_handle, &peer_addr, PROBE_TX_HANDLE,
  1671	                         value, length);
  1672	}
