  1674	static uint32_t probe_elapsed_ms(uint64_t started_us)
  1675	{
  1676	  uint64_t ended_us;
  1677	  uint64_t milliseconds;
  1678	
  1679	  if (probe_get_monotonic_us(&ended_us) < 0 || ended_us < started_us)
  1680	    {
  1681	      return 0;
  1682	    }
  1683	
  1684	  milliseconds = (ended_us - started_us) / 1000ULL;
  1685	  return milliseconds > UINT32_MAX ? UINT32_MAX : (uint32_t)milliseconds;
  1686	}
