  1754	/* Future gesture producers must use this bounded publisher rather than
  1755	 * calling a GATT API.  It is task-context only, never ISR-context.
  1756	 */
  1757	
  1758	static int probe_publish_gesture(uint8_t gesture, uint8_t confidence,
  1759	                                 uint8_t flags, uint8_t battery,
  1760	                                 uint64_t event_monotonic_us)
  1761	{
  1762	  struct probe_gesture_record_s *record;
  1763	  uint64_t now_monotonic_us;
  1764	  uint64_t timestamp_ms;
  1765	  uint32_t generation;
  1766	  uint32_t used;
  1767	  bool synced;
  1768	
  1769	  if (probe_get_monotonic_us(&now_monotonic_us) < 0)
  1770	    {
  1771	      return -1;
  1772	    }
  1773	
  1774	  if (event_monotonic_us == 0)
  1775	    {
  1776	      event_monotonic_us = now_monotonic_us;
  1777	    }
  1778	
  1779	  pthread_mutex_lock(&g_state_lock);
  1780	  generation = __atomic_load_n(&g_connection_generation, __ATOMIC_ACQUIRE);
  1781	  if (!g_peer_connected)
  1782	    {
  1783	      pthread_mutex_unlock(&g_state_lock);
  1784	      return -1;
  1785	    }
  1786	
  1787	  used = g_gesture_rx_head - g_gesture_rx_tail;
  1788	  if (used >= PROBE_GESTURE_QUEUE_DEPTH)
  1789	    {
  1790	      g_gesture_queue_full++;
  1791	      pthread_mutex_unlock(&g_state_lock);
  1792	      return -1;
  1793	    }
  1794	
  1795	  synced = g_gesture_time_synced;
  1796	  if (synced && event_monotonic_us < g_gesture_sync_monotonic_us)
  1797	    {
  1798	      event_monotonic_us = now_monotonic_us;
  1799	    }
  1800	
  1801	  timestamp_ms = synced ?
  1802	    g_gesture_sync_unix_ms +
  1803	      (event_monotonic_us - g_gesture_sync_monotonic_us) / 1000ULL :
  1804	    event_monotonic_us / 1000ULL;
  1805	  if (synced)
  1806	    {
  1807	      flags |= 0x01;
  1808	    }
  1809	  else
  1810	    {
  1811	      flags &= (uint8_t)~0x01;
  1812	    }
  1813	
  1814	  record = &g_gesture_queue[g_gesture_rx_head %
  1815	                            PROBE_GESTURE_QUEUE_DEPTH];
  1816	  memset(record, 0, sizeof(*record));
  1817	  record->connection_generation = generation;
  1818	  record->packet_id = g_gesture_next_packet_id++;
  1819	  record->event[0] = 1;
  1820	  record->event[1] = 0x01;
  1821	  probe_put_le16(&record->event[2], record->packet_id);
  1822	  probe_put_le64(&record->event[4], timestamp_ms);
  1823	  record->event[12] = gesture;
  1824	  record->event[13] = confidence;
  1825	  record->event[14] = flags;
  1826	  record->event[15] = battery;
  1827	  g_gesture_rx_head++;
  1828	  g_gesture_enqueued++;
  1829	  pthread_mutex_unlock(&g_state_lock);
  1830	
  1831	  sem_post(&g_rx_sem);
  1832	  return 0;
  1833	}
  1834	
  1835	static void probe_gesture_time_sync(const uint8_t *value)
  1836	{
  1837	  uint64_t monotonic_us;
  1838	  uint64_t unix_ms;
  1839	
  1840	  if (probe_get_monotonic_us(&monotonic_us) < 0)
  1841	    {
  1842	      printf("openvela_ble_probe: gesture time sync clock failed\n");
  1843	      return;
  1844	    }
  1845	
  1846	  pthread_mutex_lock(&g_state_lock);
  1847	  unix_ms = probe_get_le64(value);
  1848	  g_gesture_sync_unix_ms = unix_ms;
  1849	  g_gesture_sync_monotonic_us = monotonic_us;
  1850	  g_gesture_time_synced = true;
  1851	  pthread_mutex_unlock(&g_state_lock);
  1852	  printf("openvela_ble_probe: gesture time synchronized unix_ms=%" PRIu64
  1853	         " monotonic_us=%" PRIu64 "\n", unix_ms, monotonic_us);
  1854	}
