  1856	static void probe_gesture_ack(uint16_t packet_id, uint32_t generation)
  1857	{
  1858	  struct probe_gesture_record_s *record;
  1859	  bool matched = false;
  1860	
  1861	  pthread_mutex_lock(&g_state_lock);
  1862	  if (g_gesture_rx_tail != g_gesture_rx_head)
  1863	    {
  1864	      record = &g_gesture_queue[g_gesture_rx_tail %
  1865	                                PROBE_GESTURE_QUEUE_DEPTH];
  1866	      if (record->connection_generation == generation &&
  1867	          record->packet_id == packet_id && record->send_count != 0)
  1868	        {
  1869	          memset(record, 0, sizeof(*record));
  1870	          g_gesture_rx_tail++;
  1871	          g_gesture_acked++;
  1872	          matched = true;
  1873	        }
  1874	    }
  1875	  pthread_mutex_unlock(&g_state_lock);
  1876	
  1877	  if (matched)
  1878	    {
  1879	      printf("openvela_ble_probe: gesture ACK packet_id=%u\n", packet_id);
  1880	    }
  1881	}
  1882	
  1883	static void probe_process_gesture_tx(void)
  1884	{
  1885	  static const uint16_t retry_delays_ms[PROBE_GESTURE_MAX_SENDS] =
  1886	    {
  1887	      500, 1000, 2000
  1888	    };
  1889	  struct probe_gesture_record_s *record;
  1890	  uint8_t event[PROBE_GESTURE_EVENT_SIZE];
  1891	  uint64_t now_ms;
  1892	  uint32_t generation;
  1893	  uint16_t packet_id = 0;
  1894	  uint8_t send_count = 0;
  1895	  bool send = false;
  1896	  bool dropped = false;
  1897	  bt_status_t status;
  1898	
  1899	  if (probe_monotonic_ms(&now_ms) < 0)
  1900	    {
  1901	      return;
  1902	    }
  1903	
  1904	  pthread_mutex_lock(&g_state_lock);
  1905	  generation = __atomic_load_n(&g_connection_generation, __ATOMIC_ACQUIRE);
  1906	  if (g_gesture_rx_tail != g_gesture_rx_head)
  1907	    {
  1908	      record = &g_gesture_queue[g_gesture_rx_tail %
  1909	                                PROBE_GESTURE_QUEUE_DEPTH];
  1910	      if (!g_peer_connected || !g_notify_enabled ||
  1911	          record->connection_generation != generation)
  1912	        {
  1913	          if (record->connection_generation != generation)
  1914	            {
  1915	              g_gesture_rx_tail = g_gesture_rx_head;
  1916	            }
  1917	        }
  1918	      else if (record->send_count == 0 || now_ms >= record->next_retry_ms)
  1919	        {
  1920	          if (record->send_count >= PROBE_GESTURE_MAX_SENDS)
  1921	            {
  1922	              packet_id = record->packet_id;
  1923	              memset(record, 0, sizeof(*record));
  1924	              g_gesture_rx_tail++;
  1925	              g_gesture_dropped++;
  1926	              dropped = true;
  1927	            }
  1928	          else
  1929	            {
  1930	              packet_id = record->packet_id;
  1931	              memcpy(event, record->event, sizeof(event));
  1932	              record->send_count++;
  1933	              send_count = record->send_count;
  1934	              record->next_retry_ms =
  1935	                now_ms + retry_delays_ms[send_count - 1];
  1936	              if (send_count > 1)
  1937	                {
  1938	                  g_gesture_retransmitted++;
  1939	                }
  1940	              send = true;
  1941	            }
  1942	        }
  1943	    }
  1944	  pthread_mutex_unlock(&g_state_lock);
  1945	
  1946	  if (dropped)
  1947	    {
  1948	      printf("openvela_ble_probe: gesture dropped packet_id=%u\n",
  1949	             packet_id);
  1950	      return;
  1951	    }
  1952	
  1953	  if (!send)
  1954	    {
  1955	      return;
  1956	    }
  1957	
  1958	  status = probe_notify(g_service_handle, event, sizeof(event));
  1959	  if (status != BT_STATUS_SUCCESS)
  1960	    {
  1961	      pthread_mutex_lock(&g_state_lock);
  1962	      g_gesture_tx_status_nonzero++;
  1963	      pthread_mutex_unlock(&g_state_lock);
  1964	    }
  1965	
  1966	  if (send_count > 1)
  1967	    {
  1968	      printf("openvela_ble_probe: gesture retransmit packet_id=%u "
  1969	             "attempt=%u status=%d\n",
  1970	             packet_id, send_count, status);
  1971	    }
  1972	}
