  1974	static uint16_t probe_tx_cccd_written(gatts_handle_t srv_handle,
  1975	                                      bt_address_t *addr,
  1976	                                      uint16_t attr_handle,
  1977	                                      const uint8_t *value,
  1978	                                      uint16_t length,
  1979	                                      uint16_t offset)
