  2007	static void probe_process_frame(gatts_handle_t srv_handle,
  2008	                                const uint8_t *value, uint16_t length,
  2009	                                uint32_t connection_generation)
  2010	{
  2011	  uint8_t response[21];
  2012	  uint8_t *reply;
  2013	  uint16_t reply_len;
  2014	  uint32_t elapsed_ms;
  2015	  uint32_t id_or_seq;
  2016	  uint32_t seq;
  2017	  bt_status_t status;
  2018	
  2019	  if (length == 4 && memcmp(value, "PING", 4) == 0)
  2020	    {
  2021	      reply = g_pong;
  2022	      reply_len = sizeof(g_pong);
  2023	      printf("openvela_ble_probe: RX PING\n");
  2024	    }
  2025	  else if (length >= 1 && value[0] == 0x01)
  2026	    {
  2027	      if (length < 5)
  2028	        {
  2029	          printf("openvela_ble_probe: short binary PING length=%u\n",
  2030	                 length);
  2031	          return;
  2032	        }
  2033	
  2034	      id_or_seq = probe_get_le32(&value[1]);
  2035	      response[0] = 0x81;
  2036	      probe_put_le32(&response[1], id_or_seq);
  2037	      printf("openvela_ble_probe: RX binary PING seq=%lu\n",
  2038	             (unsigned long)id_or_seq);
  2039	      status = probe_notify(srv_handle, response, 5);
  2040	      printf("openvela_ble_probe: TX binary PONG status=%d\n", status);
  2041	      return;
  2042	    }
  2043	  else if (length >= 1 && value[0] == PROBE_RELIABLE39_REQUEST_TYPE)
  2044	    {
  2045	      uint16_t expected_crc;
  2046	      uint16_t received_crc;
  2047	
  2048	      if (length != PROBE_RELIABLE39_FRAME_SIZE)
  2049	        {
  2050	          __atomic_fetch_add(&g_reliable39_bad_length, 1,
  2051	                             __ATOMIC_RELAXED);
  2052	          return;
  2053	        }
  2054	
  2055	      received_crc = probe_get_le16(&value[PROBE_RELIABLE39_CRC_OFFSET]);
  2056	      expected_crc = probe_crc16_ccitt_false(
  2057	        value, PROBE_RELIABLE39_CRC_OFFSET);
  2058	      if (received_crc != expected_crc)
  2059	        {
  2060	          __atomic_fetch_add(&g_reliable39_bad_crc, 1, __ATOMIC_RELAXED);
  2061	          return;
  2062	        }
  2063	
  2064	      id_or_seq = probe_get_le32(&value[1]);
  2065	      if (g_reliable39.valid &&
  2066	          g_reliable39.connection_generation == connection_generation &&
  2067	          g_reliable39.sequence == id_or_seq)
  2068	        {
  2069	          __atomic_fetch_add(&g_reliable39_duplicates, 1,
  2070	                             __ATOMIC_RELAXED);
  2071	        }
  2072	      else
  2073	        {
  2074	          g_reliable39.response[0] = PROBE_RELIABLE39_RESPONSE_TYPE;
  2075	          probe_put_le32(&g_reliable39.response[1], id_or_seq);
  2076	          memcpy(&g_reliable39.response[5], &value[5],
  2077	                 PROBE_RELIABLE39_PAYLOAD_SIZE);
  2078	          probe_put_le16(&g_reliable39.response[PROBE_RELIABLE39_CRC_OFFSET],
  2079	                         probe_crc16_ccitt_false(
  2080	                           g_reliable39.response,
  2081	                           PROBE_RELIABLE39_CRC_OFFSET));
  2082	          g_reliable39.connection_generation = connection_generation;
  2083	          g_reliable39.sequence = id_or_seq;
  2084	          g_reliable39.valid = true;
  2085	          __atomic_fetch_add(&g_reliable39_rx_ok, 1, __ATOMIC_RELAXED);
  2086	        }
  2087	
  2088	      __atomic_fetch_add(&g_reliable39_tx_attempted, 1, __ATOMIC_RELAXED);
  2089	      status = probe_notify(srv_handle, g_reliable39.response,
  2090	                            sizeof(g_reliable39.response));
  2091	      if (status != BT_STATUS_SUCCESS)
  2092	        {
  2093	          __atomic_fetch_add(&g_reliable39_tx_status_nonzero, 1,
  2094	                             __ATOMIC_RELAXED);
  2095	        }
  2096	
  2097	      return;
  2098	    }
  2099	  else if (length >= 1 && value[0] == PROBE_GESTURE_TIME_SYNC_TYPE)
  2100	    {
  2101	      if (length != 9)
  2102	        {
  2103	          printf("openvela_ble_probe: invalid gesture time sync length=%u\n",
  2104	                 length);
  2105	          return;
  2106	        }
  2107	
  2108	      probe_gesture_time_sync(&value[1]);
  2109	      return;
  2110	    }
  2111	  else if (length >= 1 && value[0] == PROBE_GESTURE_ACK_TYPE)
  2112	    {
  2113	      if (length != 3)
  2114	        {
  2115	          printf("openvela_ble_probe: invalid gesture ACK length=%u\n",
  2116	                 length);
  2117	          return;
  2118	        }
  2119	
  2120	      probe_gesture_ack(probe_get_le16(&value[1]),
  2121	                        connection_generation);
  2122	      return;
  2123	    }
  2124	  else if (length >= 1 && value[0] == PROBE_GESTURE_INJECT_TYPE)
  2125	    {
  2126	      if (length != 5)
  2127	        {
  2128	          printf("openvela_ble_probe: invalid gesture inject length=%u\n",
  2129	                 length);
  2130	          return;
  2131	        }
  2132	
  2133	#if BLE_PROBE_GESTURE_TEST_INJECT
  2134	      {
  2135	        struct probe_game_command command;
  2136	
  2137	        command.connection_generation = connection_generation;
  2138	        command.gesture = value[1];
  2139	        command.confidence = value[2];
  2140	        command.flags = value[3];
  2141	        command.battery = value[4];
  2142	        printf("openvela_ble_probe: gesture test inject game_queue=%d\n",
  2143	               probe_game_submit_command(&command));
  2144	      }
  2145	#else
  2146	      printf("openvela_ble_probe: gesture test inject disabled\n");
  2147	#endif
  2148	      return;
  2149	    }
  2150	  else if (length >= 1 && value[0] == 0x10)
  2151	    {
  2152	      if (length < 5)
  2153	        {
  2154	          printf("openvela_ble_probe: short START length=%u\n", length);
  2155	          return;
  2156	        }
  2157	
  2158	      id_or_seq = probe_get_le32(&value[1]);
  2159	      memset(&g_throughput, 0, sizeof(g_throughput));
  2160	      g_throughput.active = true;
  2161	      g_throughput.test_id = id_or_seq;
  2162	
  2163	      response[0] = 0x90;
  2164	      probe_put_le32(&response[1], id_or_seq);
  2165	      printf("openvela_ble_probe: throughput START test_id=%lu\n",
  2166	             (unsigned long)id_or_seq);
  2167	      status = probe_notify(srv_handle, response, 5);
  2168	      printf("openvela_ble_probe: throughput START_ACK status=%d\n", status);
  2169	      return;
  2170	    }
  2171	  else if (length >= 1 && value[0] == 0x11)
  2172	    {
  2173	      if (length < 5)
  2174	        {
  2175	          printf("openvela_ble_probe: short DATA length=%u\n", length);
  2176	          return;
  2177	        }
  2178	
  2179	      if (!g_throughput.active)
  2180	        {
  2181	          printf("openvela_ble_probe: DATA without active test\n");
  2182	          return;
  2183	        }
  2184	
  2185	      seq = probe_get_le32(&value[1]);
  2186	      if (!g_throughput.timing)
  2187	        {
  2188	          if (probe_get_monotonic_us(&g_throughput.started_us) == 0)
  2189	            {
  2190	              g_throughput.timing = true;
  2191	            }
  2192	          else
  2193	            {
  2194	              printf("openvela_ble_probe: monotonic clock failed\n");
  2195	            }
  2196	        }
  2197	
  2198	      g_throughput.frames++;
  2199	      g_throughput.payload_bytes += length - 5;
  2200	
  2201	      if (!g_throughput.have_expected_seq)
  2202	        {
  2203	          g_throughput.expected_seq = seq + 1;
  2204	          g_throughput.have_expected_seq = true;
  2205	        }
  2206	      else if (seq == g_throughput.expected_seq)
  2207	        {
  2208	          g_throughput.expected_seq++;
  2209	        }
  2210	      else if (seq > g_throughput.expected_seq)
  2211	        {
  2212	          g_throughput.missing_frames += seq - g_throughput.expected_seq;
  2213	          g_throughput.expected_seq = seq + 1;
  2214	        }
  2215	      else
  2216	        {
  2217	          g_throughput.missing_frames++;
  2218	        }
  2219	
  2220	      return;
  2221	    }
  2222	  else if (length >= 1 && value[0] == 0x12)
  2223	    {
  2224	      if (length < 5)
  2225	        {
  2226	          printf("openvela_ble_probe: short END length=%u\n", length);
  2227	          return;
  2228	        }
  2229	
  2230	      id_or_seq = probe_get_le32(&value[1]);
  2231	      if (!g_throughput.active || id_or_seq != g_throughput.test_id)
  2232	        {
  2233	          printf("openvela_ble_probe: unmatched END test_id=%lu\n",
  2234	                 (unsigned long)id_or_seq);
  2235	          return;
  2236	        }
  2237	
  2238	      elapsed_ms = g_throughput.timing ?
  2239	                   probe_elapsed_ms(g_throughput.started_us) : 0;
  2240	      response[0] = 0x91;
  2241	      probe_put_le32(&response[1], g_throughput.test_id);
  2242	      probe_put_le32(&response[5], g_throughput.frames);
  2243	      probe_put_le32(&response[9], g_throughput.payload_bytes);
  2244	      probe_put_le32(&response[13], elapsed_ms);
  2245	      probe_put_le32(&response[17], g_throughput.missing_frames);
  2246	
  2247	      printf("openvela_ble_probe: throughput END test_id=%lu frames=%lu "
  2248	             "payload=%lu elapsed_ms=%lu missing=%lu\n",
  2249	             (unsigned long)g_throughput.test_id,
  2250	             (unsigned long)g_throughput.frames,
  2251	             (unsigned long)g_throughput.payload_bytes,
  2252	             (unsigned long)elapsed_ms,
  2253	             (unsigned long)g_throughput.missing_frames);
  2254	      status = probe_notify(srv_handle, response, sizeof(response));
  2255	      printf("openvela_ble_probe: throughput REPORT status=%d\n", status);
  2256	      probe_print_rx_queue_stats();
  2257	      memset(&g_throughput, 0, sizeof(g_throughput));
  2258	      return;
  2259	    }
  2260	  else
  2261	    {
  2262	      reply = g_error;
  2263	      reply_len = sizeof(g_error);
  2264	      printf("openvela_ble_probe: RX unknown command\n");
  2265	    }
  2266	
  2267	  status = probe_notify(srv_handle, reply, reply_len);
  2268	  printf("openvela_ble_probe: TX notify status=%d\n", status);
  2269	}
