   254	static int probe_parse_startup_uptime(int argc, char *argv[],
   255	                                      uint64_t *target_ms)
   256	{
   257	  const char *cursor;
   258	  uint32_t value = 0;
   259	
   260	  if (argc == 1)
   261	    {
   262	      *target_ms = MIN_BLE_STARTUP_UPTIME_MS;
   263	      return 0;
   264	    }
   265	
   266	  if (argc == 2 && argv[1][0] != '\0')
   267	    {
   268	      for (cursor = argv[1]; *cursor != '\0'; cursor++)
   269	        {
   270	          if (*cursor < '0' || *cursor > '9')
   271	            {
   272	              goto invalid;
   273	          }
   274	
   275	          value = value * 10u + (uint32_t)(*cursor - '0');
   276	          if (value > 15000u)
   277	            {
   278	              goto invalid;
   279	            }
   280	          }
   281	
   282	      if (value >= 5000u && value <= 15000u && value % 250u == 0)
   283	        {
   284	          *target_ms = value;
   285	          return 0;
   286	        }
   287	    }
   288	
   289	invalid:
   290	  printf("Usage: openvela_ble_probe "
   291	         "[min_uptime_ms: 5000..15000, step 250]\n");
   292	  return -1;
   293	}
   294	
   295	static int probe_wait_for_ble_startup(uint64_t target_ms)
   296	{
   297	  uint64_t now_us;
   298	  uint64_t uptime_ms;
   299	  uint64_t remaining_ms;
   300	  uint64_t sleep_ms;
   301	  bool delay_logged = false;
   302	
   303	  for (;;)
   304	    {
   305	      if (probe_get_monotonic_us(&now_us) < 0)
   306	        {
   307	          printf("openvela_ble_probe: failed to read system uptime\n");
   308	          return -1;
   309	        }
   310	
   311	      uptime_ms = now_us / 1000ULL;
   312	      if (uptime_ms >= target_ms)
   313	        {
   314	          if (!delay_logged)
   315	            {
   316	              printf("openvela_ble_probe: BLE startup target=%llu ms "
   317	                     "already satisfied\n",
   318	                     (unsigned long long)target_ms);
   319	            }
   320	
   321	          return 0;
   322	        }
   323	
   324	      remaining_ms = target_ms - uptime_ms;
   325	      if (!delay_logged)
   326	        {
   327	          printf("openvela_ble_probe: delaying BLE start %llu ms "
   328	                 "for platform readiness (target=%llu ms)\n",
   329	                 (unsigned long long)remaining_ms,
   330	                 (unsigned long long)target_ms);
   331	          delay_logged = true;
   332	        }
   333	
   334	      sleep_ms = remaining_ms > 100u ? 100u : remaining_ms;
   335	      usleep((useconds_t)(sleep_ms * 1000u));
   336	    }
   337	}
