  2088	      __atomic_fetch_add(&g_reliable39_tx_attempted, 1, __ATOMIC_RELAXED);
  2089	      status = probe_notify(srv_handle, g_reliable39.response,
  2090	                            sizeof(g_reliable39.response));
  2091	      if (status != BT_STATUS_SUCCESS)
  2092	        {
  2093	          __atomic_fetch_add(&g_reliable39_tx_status_nonzero, 1,
  2094	                             __ATOMIC_RELAXED);
  2095	        }
  2096	
  2097	      return;
  2098	    }
  2099	  else if (length >= 1 && value[0] == PROBE_GESTURE_TIME_SYNC_TYPE)
  2100	    {
  2101	      if (length != 9)
  2102	        {
  2103	          printf("openvela_ble_probe: invalid gesture time sync length=%u\n",
  2104	                 length);
  2105	          return;
  2106	        }
  2107	
  2108	      probe_gesture_time_sync(&value[1]);
  2109	      return;
  2110	    }
  2111	  else if (length >= 1 && value[0] == PROBE_GESTURE_ACK_TYPE)
  2112	    {
  2113	      if (length != 3)
  2114	        {
  2115	          printf("openvela_ble_probe: invalid gesture ACK length=%u\n",
  2116	                 length);
  2117	          return;
