  2123	    }
  2124	  else if (length >= 1 && value[0] == PROBE_GESTURE_INJECT_TYPE)
  2125	    {
  2126	      if (length != 5)
  2127	        {
  2128	          printf("openvela_ble_probe: invalid gesture inject length=%u\n",
  2129	                 length);
  2130	          return;
  2131	        }
  2132	
  2133	#if BLE_PROBE_GESTURE_TEST_INJECT
  2134	      {
  2135	        struct probe_game_command command;
  2136	
  2137	        command.connection_generation = connection_generation;
  2138	        command.gesture = value[1];
  2139	        command.confidence = value[2];
