  2200	
  2201	      if (!g_throughput.have_expected_seq)
  2202	        {
  2203	          g_throughput.expected_seq = seq + 1;
  2204	          g_throughput.have_expected_seq = true;
  2205	        }
  2206	      else if (seq == g_throughput.expected_seq)
  2207	        {
  2208	          g_throughput.expected_seq++;
  2209	        }
  2210	      else if (seq > g_throughput.expected_seq)
  2211	        {
  2212	          g_throughput.missing_frames += seq - g_throughput.expected_seq;
  2213	          g_throughput.expected_seq = seq + 1;
  2214	        }
  2215	      else
  2216	        {
  2217	          g_throughput.missing_frames++;
  2218	        }
  2219	
  2220	      return;
  2221	    }
  2222	  else if (length >= 1 && value[0] == 0x12)
  2223	    {
  2224	      if (length < 5)
  2225	        {
  2226	          printf("openvela_ble_probe: short END length=%u\n", length);
  2227	          return;
  2228	        }
  2229	
  2230	      id_or_seq = probe_get_le32(&value[1]);
  2231	      if (!g_throughput.active || id_or_seq != g_throughput.test_id)
  2232	        {
  2233	          printf("openvela_ble_probe: unmatched END test_id=%lu\n",
  2234	                 (unsigned long)id_or_seq);
  2235	          return;
  2236	        }
  2237	
  2238	      elapsed_ms = g_throughput.timing ?
  2239	                   probe_elapsed_ms(g_throughput.started_us) : 0;
  2240	      response[0] = 0x91;
  2241	      probe_put_le32(&response[1], g_throughput.test_id);
  2242	      probe_put_le32(&response[5], g_throughput.frames);
  2243	      probe_put_le32(&response[9], g_throughput.payload_bytes);
  2244	      probe_put_le32(&response[13], elapsed_ms);
  2245	      probe_put_le32(&response[17], g_throughput.missing_frames);
  2246	
  2247	      printf("openvela_ble_probe: throughput END test_id=%lu frames=%lu "
  2248	             "payload=%lu elapsed_ms=%lu missing=%lu\n",
  2249	             (unsigned long)g_throughput.test_id,
  2250	             (unsigned long)g_throughput.frames,
  2251	             (unsigned long)g_throughput.payload_bytes,
  2252	             (unsigned long)elapsed_ms,
  2253	             (unsigned long)g_throughput.missing_frames);
  2254	      status = probe_notify(srv_handle, response, sizeof(response));
  2255	      printf("openvela_ble_probe: throughput REPORT status=%d\n", status);
  2256	      probe_print_rx_queue_stats();
  2257	      memset(&g_throughput, 0, sizeof(g_throughput));
  2258	      return;
  2259	    }
  2260	  else
  2261	    {
  2262	      reply = g_error;
  2263	      reply_len = sizeof(g_error);
  2264	      printf("openvela_ble_probe: RX unknown command\n");
  2265	    }
  2266	
  2267	  status = probe_notify(srv_handle, reply, reply_len);
  2268	  printf("openvela_ble_probe: TX notify status=%d\n", status);
  2269	}
