  2271	static uint16_t probe_rx_written(gatts_handle_t srv_handle,
  2272	                                 bt_address_t *addr,
  2273	                                 uint16_t attr_handle,
  2274	                                 const uint8_t *value,
  2275	                                 uint16_t length,
  2276	                                 uint16_t offset)
  2277	{
  2278	  struct probe_rx_slot_s *slot;
  2279	  uint32_t generation;
  2280	  uint32_t head;
  2281	  uint32_t tail;
  2282	  uint32_t used;
  2283	
  2284	  (void)srv_handle;
  2285	  (void)attr_handle;
  2286	
  2287	  if (offset != 0 || length > PROBE_RX_FRAME_MAX)
  2288	    {
  2289	      __atomic_fetch_add(&g_rx_invalid_length, 1, __ATOMIC_RELAXED);
  2290	      return 0;
  2291	    }
  2292	
  2293	  generation = __atomic_load_n(&g_connection_generation, __ATOMIC_ACQUIRE);
  2294	  head = __atomic_load_n(&g_rx_head, __ATOMIC_RELAXED);
  2295	  tail = __atomic_load_n(&g_rx_tail, __ATOMIC_ACQUIRE);
  2296	  used = head - tail;
  2297	  if (used >= PROBE_RX_QUEUE_DEPTH)
  2298	    {
  2299	      __atomic_fetch_add(&g_rx_drop_full, 1, __ATOMIC_RELAXED);
  2300	      return 0;
  2301	    }
  2302	
  2303	  slot = &g_rx_queue[head % PROBE_RX_QUEUE_DEPTH];
  2304	  memcpy(&slot->addr, addr, sizeof(slot->addr));
  2305	  slot->connection_generation = generation;
  2306	  slot->length = length;
  2307	  slot->offset = offset;
  2308	  memcpy(slot->value, value, length);
  2309	  used++;
  2310	  if (used >
  2311	      __atomic_load_n(&g_rx_high_water, __ATOMIC_RELAXED))
  2312	    {
  2313	      __atomic_store_n(&g_rx_high_water, used, __ATOMIC_RELAXED);
  2314	    }
  2315	
  2316	  /* Publish only after the complete slot is visible to the consumer. */
  2317	
  2318	  __atomic_store_n(&g_rx_head, head + 1, __ATOMIC_RELEASE);
  2319	
  2320	  __atomic_fetch_add(&g_rx_enqueued, 1, __ATOMIC_RELAXED);
  2321	  sem_post(&g_rx_sem);
  2322	  return length;
  2323	}
  2324	
  2325	static void *probe_communication_thread(void *arg)
  2326	{
  2327	  struct probe_game_result game_result;
  2328	  struct probe_rx_slot_s slot;
  2329	  bt_address_t peer_addr;
  2330	  uint32_t generation;
  2331	  uint32_t active_generation = 0;
  2332	  uint32_t head;
  2333	  uint32_t tail;
  2334	  bool connected;
  2335	  bool have_slot;
  2336	  int wait_status;
  2337	  struct timespec wait_until;
  2338	
  2339	  (void)arg;
  2340	
  2341	  for (;;)
  2342	    {
  2343	      if (clock_gettime(CLOCK_REALTIME, &wait_until) < 0)
  2344	        {
  2345	          continue;
  2346	        }
  2347	
  2348	      wait_until.tv_nsec += PROBE_GESTURE_WORKER_POLL_MS * 1000000L;
  2349	      if (wait_until.tv_nsec >= 1000000000L)
  2350	        {
  2351	          wait_until.tv_sec++;
  2352	          wait_until.tv_nsec -= 1000000000L;
  2353	        }
  2354	
  2355	      do
  2356	        {
  2357	          wait_status = sem_timedwait(&g_rx_sem, &wait_until);
  2358	        }
  2359	      while (wait_status < 0 && errno == EINTR);
  2360	
  2361	      if (wait_status < 0 && errno != ETIMEDOUT)
  2362	        {
  2363	          continue;
  2364	        }
  2365	
  2366	      tail = __atomic_load_n(&g_rx_tail, __ATOMIC_RELAXED);
  2367	      head = __atomic_load_n(&g_rx_head, __ATOMIC_ACQUIRE);
  2368	      have_slot = tail != head;
  2369	      if (have_slot)
  2370	        {
  2371	          memcpy(&slot, &g_rx_queue[tail % PROBE_RX_QUEUE_DEPTH],
  2372	                 sizeof(slot));
  2373	          __atomic_store_n(&g_rx_tail, tail + 1, __ATOMIC_RELEASE);
  2374	        }
  2375	
  2376	      pthread_mutex_lock(&g_state_lock);
  2377	      generation = __atomic_load_n(&g_connection_generation,
  2378	                                   __ATOMIC_ACQUIRE);
  2379	      connected = g_peer_connected;
  2380	      memcpy(&peer_addr, &g_peer_addr, sizeof(peer_addr));
  2381	      pthread_mutex_unlock(&g_state_lock);
  2382	
  2383	      if (generation != active_generation)
  2384	        {
  2385	          memset(&g_throughput, 0, sizeof(g_throughput));
  2386	          memset(&g_reliable39, 0, sizeof(g_reliable39));
  2387	          active_generation = generation;
  2388	        }
  2389	
  2390	      if (have_slot &&
  2391	          (!connected || slot.connection_generation != generation ||
  2392	           memcmp(&slot.addr, &peer_addr, sizeof(peer_addr)) != 0))
  2393	        {
  2394	          __atomic_fetch_add(&g_rx_stale, 1, __ATOMIC_RELAXED);
  2395	          have_slot = false;
  2396	        }
  2397	
  2398	      if (have_slot)
  2399	        {
  2400	          probe_process_frame(g_service_handle, slot.value, slot.length,
  2401	                              generation);
  2402	        }
  2403	
  2404	      while (probe_game_take_ble_result(&game_result))
  2405	        {
  2406	          int publish_status;
  2407	
  2408	          if (!connected || game_result.connection_generation != generation)
  2409	            {
  2410	              printf("openvela_ble_probe: stale game result dropped"
  2411	                     " generation=%lu current=%lu\n",
  2412	                     (unsigned long)game_result.connection_generation,
  2413	                     (unsigned long)generation);
  2414	              continue;
  2415	            }
  2416	
  2417	          publish_status = probe_publish_gesture(game_result.gesture,
  2418	                                                 game_result.confidence,
  2419	                                                 game_result.flags,
  2420	                                                 game_result.battery,
  2421	                                                 game_result.monotonic_us);
  2422	
  2423	          printf("openvela_ble_probe: game result publish gesture=%u"
  2424	                 " session=%lu combo=%lu status=%d\n",
  2425	                 game_result.gesture,
  2426	                 (unsigned long)game_result.game_session,
  2427	                 (unsigned long)game_result.combo, publish_status);
  2428	        }
  2429	
  2430	      probe_process_gesture_tx();
  2431	    }
  2432	
  2433	  return NULL;
  2434	}
